class TopVotedCandidate {
    vector<int> times;
    vector<int> leaders;
public:
    TopVotedCandidate(vector<int>& persons, vector<int>& times) : times(times) {
        unordered_map<int, int> count;
        int leader = -1, max_votes = 0;
        for (int p : persons) {
            if (++count[p] >= max_votes) {
                max_votes = count[p];
                leader = p;
            }
            leaders.push_back(leader);
        }
    }

    int q(int t) {
        auto it = upper_bound(times.begin(), times.end(), t) - 1;
        int idx = distance(times.begin(), it);
        return leaders[idx];
    }
};

import java.util.*;

class TopVotedCandidate {
    private int[] times;
    private int[] leaders;

    public TopVotedCandidate(int[] persons, int[] times) {
        this.times = times;
        this.leaders = new int[persons.length];
        Map<Integer, Integer> count = new HashMap<>();
        int leader = -1, maxVotes = 0;
        for (int i = 0; i < persons.length; i++) {
            int p = persons[i];
            int c = count.getOrDefault(p, 0) + 1;
            count.put(p, c);
            if (c >= maxVotes) {
                maxVotes = c;
                leader = p;
            }
            leaders[i] = leader;
        }
    }

    public int q(int t) {
        int idx = Arrays.binarySearch(times, t);
        if (idx < 0) idx = -idx - 2;
        return leaders[idx];
    }
}

/**
 * @param {number[]} persons
 * @param {number[]} times
 */
var TopVotedCandidate = function(persons, times) {
    this.times = times;
    this.leaders = [];
    const count = new Map();
    let leader = -1, maxVotes = 0;
    for (const p of persons) {
        const c = (count.get(p) || 0) + 1;
        count.set(p, c);
        if (c >= maxVotes) {
            maxVotes = c;
            leader = p;
        }
        this.leaders.push(leader);
    }
};

/** 
 * @param {number} t
 * @return {number}
 */
TopVotedCandidate.prototype.q = function(t) {
    let low = 0, high = this.times.length - 1;
    let idx = 0;
    while (low <= high) {
        const mid = (low + high) >> 1;
        if (this.times[mid] <= t) {
            idx = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return this.leaders[idx];
};
